static unsigned gui_small_option_mask(const lt48_small_eprom_resources*r){if(lt48_small_eprom_is_sm2965four(r))return 0x7f7f;if(lt48_small_eprom_is_elan5(r))return 0xffff;if(lt48_small_eprom_is_syntek4(r))return 0x3f;if(lt48_small_eprom_is_scenix6(r))return 0xffff;unsigned h=lt48_small_eprom_hyundai13_option_mask(r);return h?h:lt48_small_eprom_st62_option_mask(r);}
static lt48_status gui_small_set_options(lt48_small_eprom_resources*r,const unsigned char*bytes){unsigned bits=bytes[0]|bytes[1]<<8;return lt48_small_eprom_is_sm2965four(r)?lt48_small_eprom_set_sm2965four_configuration(r,bytes[0],bytes[1]):lt48_small_eprom_is_elan5(r)?lt48_small_eprom_set_elan5_configuration(r,bits,bytes[2]|bytes[3]<<8):lt48_small_eprom_is_syntek4(r)?lt48_small_eprom_set_syntek4_configuration(r,bits):lt48_small_eprom_is_scenix6(r)?lt48_small_eprom_set_scenix6_configuration(r,bits,bytes[2]|bytes[3]<<8):lt48_small_eprom_hyundai13_configuration_size(r)==16?lt48_small_eprom_set_hyundai13_extended_configuration(r,bytes,16):lt48_small_eprom_hyundai13_option_mask(r)?lt48_small_eprom_set_hyundai13_configuration(r,bits):lt48_small_eprom_set_st62_configuration(r,bits);}

static gboolean pic18_k80_editor_available(const lt48_installation *x,size_t index) {
    lt48_device_spec spec;
    return lt48_installation_resolve_device(x,index,&spec)==LT48_OK &&
        spec.configuration_set==25288 &&
        lt48_pic18_k80_configuration_binding(spec.definition_resource,spec.family_code,spec.pinmap) &&
        !strcmp(lt48_installation_complete_operation_profile(x,index),"pic18-eight-operation");
}

/* Shared by prepare and execute: parallel Page entries must bypass SPI. */
static int page_parallel_class2041(unsigned cls,unsigned definition) {
    return cls==2041u && ((definition<=14u) ||
                         (definition>=0x14u && definition<=0x1fu) || (definition>=0x21u && definition<=0x25u));
}

