typedef struct {app_widgets *widgets;GtkWindow *window;GtkWidget *selector,*apply;lt48_operation_kind operation;size_t device;uint64_t revision;} idlock_editor;
static char *idlock_region_label(unsigned capacity,unsigned choice) {
    unsigned first=0,last=0;
    if(choice==0)return g_strdup("0 — Unlocked");
    if(choice>=1 && choice<=4){first=(choice-1)*capacity/4;last=choice*capacity/4-1;}
    else if(choice==5)last=capacity/2-1;
    else if(choice==6)last=15;
    else if(choice==7){first=capacity-16;last=capacity-1;}
    else return NULL;
    return g_strdup_printf("%u — %04X–%04X (%s)",choice,first,last,choice<=4?"quarter":choice==5?"lower half":choice==6?"first page":"last page");
}
static void idlock_selection_changed(GObject *object,GParamSpec *pspec,gpointer data) {
    (void)object;(void)pspec;idlock_editor *e=data;
    unsigned choice=gtk_drop_down_get_selected(GTK_DROP_DOWN(e->selector));
    gtk_widget_set_sensitive(e->apply,choice<=7 && (e->operation!=LT48_OPERATION_SECURE || choice!=0));
}
static void idlock_apply(GtkButton *button,gpointer data) {
    (void)button;idlock_editor *e=data;app_widgets *w=e->widgets;
    unsigned choice=gtk_drop_down_get_selected(GTK_DROP_DOWN(e->selector));
    if(!w->has_selected_device || e->device!=w->selected_device_index || e->revision!=w->operation_input_revision){gtk_window_destroy(e->window);return;}
    if(choice>7 || (e->operation==LT48_OPERATION_SECURE && !choice))return;
    lt48_operation_kind operation=e->operation;w->idlock_selector=choice;
    gtk_drop_down_set_selected(GTK_DROP_DOWN(w->operation_dropdown),operation==LT48_OPERATION_SECURE?7:9);
    gtk_window_destroy(e->window);w->read_after_prepare=0;start_operation_preparation(w,operation);
}
static void idlock_editor_open(app_widgets *w,lt48_operation_kind operation) {
    lt48_device_spec spec;
    if(!w->installation || !w->has_selected_device || lt48_installation_resolve_device(w->installation,w->selected_device_index,&spec)!=LT48_OK)return;
    idlock_editor *e=g_new0(idlock_editor,1);e->widgets=w;e->device=w->selected_device_index;e->revision=w->operation_input_revision;e->operation=operation;
    e->window=GTK_WINDOW(gtk_window_new());gtk_window_set_title(e->window,"IDLock protection region");gtk_window_set_transient_for(e->window,w->window);gtk_window_set_modal(e->window,TRUE);
    GtkWidget *box=gtk_box_new(GTK_ORIENTATION_VERTICAL,8);gtk_window_set_child(e->window,box);
    gtk_box_append(GTK_BOX(box),gtk_label_new("Choose the region to protect. This is a new setting, not a live read.\nIDLock is reversible; Configuration can unlock it.\nProgram and Erase preserve the chip’s current protection region."));
    GtkStringList *choices=gtk_string_list_new(NULL);
    for(unsigned i=0;i<8;i++){char *label=idlock_region_label(spec.capacity_bytes,i);gtk_string_list_append(choices,label);g_free(label);}
    e->selector=gtk_drop_down_new(G_LIST_MODEL(choices),NULL);gtk_drop_down_set_selected(GTK_DROP_DOWN(e->selector),GTK_INVALID_LIST_POSITION);gtk_box_append(GTK_BOX(box),e->selector);
    e->apply=gtk_button_new_with_label("Prepare selected IDLock setting");gtk_widget_set_sensitive(e->apply,FALSE);gtk_box_append(GTK_BOX(box),e->apply);
    g_signal_connect(e->selector,"notify::selected",G_CALLBACK(idlock_selection_changed),e);g_signal_connect(e->apply,"clicked",G_CALLBACK(idlock_apply),e);
    g_object_set_data_full(G_OBJECT(e->window),"idlock-editor",e,g_free);gtk_window_present(e->window);
}
