static void configuration_editor_committed(
    lt48_property_model *model, gpointer user_data
) {
    app_widgets *widgets = user_data;
    char *message = g_strdup_printf(
        "%s values accepted in the editor. The decoded property binding is "
        "retained for the selected definition; live device application remains "
        "disabled until that definition's write-back callback is decoded.",
        model->title);
    gtk_label_set_text(GTK_LABEL(widgets->read_preparation), message);
    g_free(message);
}

static void xc17_configuration_editor_open(app_widgets *w) {
    lt48_xc17_resources *r=NULL;
    if(lt48_xc17_open(w->installation,w->selected_device_index,&r)!=LT48_OK)return;
    unsigned count=lt48_xc17_configuration_bits(r);lt48_xc17_close(r);
    spd_editor *e=g_new0(spd_editor,1);e->widgets=w;e->device=w->selected_device_index;e->revision=w->operation_input_revision;e->operation=LT48_OPERATION_CONFIGURATION;e->count=count;e->allow_zero=TRUE;
    e->window=GTK_WINDOW(gtk_window_new());gtk_window_set_title(e->window,"Serial PROM configuration");gtk_window_set_transient_for(e->window,w->window);gtk_window_set_modal(e->window,TRUE);
    GtkWidget *box=gtk_box_new(GTK_ORIENTATION_VERTICAL,8);gtk_window_set_child(e->window,box);
    gtk_box_append(GTK_BOX(box),gtk_label_new(count==1?
        "OTP reset polarity: High can be changed to Low once. Ordinary programming preserves it. These are requested settings; the current chip is checked before writing.":
        "OTP options can be enabled once and cannot be cleared. Ordinary programming preserves them. These are requested settings; the current chip is checked before writing."));
    static const char *labels[]={"Reset active low","Express mode enabled","Busy pull-down enabled"};
    for(unsigned i=0;i<count;i++){
        e->bits[i]=gtk_check_button_new_with_label(count==1?"Reset polarity High (unchecked: Low)":labels[i]);
        gtk_check_button_set_active(GTK_CHECK_BUTTON(e->bits[i]),count==1);gtk_box_append(GTK_BOX(box),e->bits[i]);
    }
    e->apply=gtk_button_new_with_label("Prepare configuration");gtk_box_append(GTK_BOX(box),e->apply);
    g_signal_connect(e->apply,"clicked",G_CALLBACK(spd_apply),e);g_object_set_data_full(G_OBJECT(e->window),"xc17-editor",e,g_free);gtk_window_present(e->window);
}

typedef struct {app_widgets*w;GtkWindow*window;GtkWidget*flags[3],*code;unsigned mask;size_t device;uint64_t revision;} config_memory_editor;
static void config_memory_apply(GtkButton*b,gpointer data){
    (void)b;config_memory_editor*e=data;app_widgets*w=e->w;
    if(w->selected_device_index!=e->device||w->operation_input_revision!=e->revision){gtk_window_destroy(e->window);return;}
    unsigned flags=0;for(unsigned i=0;i<3;i++)if(e->flags[i]&&gtk_check_button_get_active(GTK_CHECK_BUTTON(e->flags[i])))flags|=e->mask==1?1:1u<<(20+i);
    const char*txt=e->code?gtk_editable_get_text(GTK_EDITABLE(e->code)):"0";char*end=NULL;guint64 code=g_ascii_strtoull(txt,&end,16);
    if(!*txt||*end||code>UINT32_MAX){gtk_label_set_text(GTK_LABEL(w->read_preparation),"User code must be a hexadecimal 32-bit value.");return;}
    w->spd_mask=flags;w->gaaf_configuration_raw=(unsigned)code;gtk_drop_down_set_selected(GTK_DROP_DOWN(w->operation_dropdown),9);gtk_window_destroy(e->window);w->read_after_prepare=0;start_operation_preparation(w,LT48_OPERATION_CONFIGURATION);
}
static void config_memory_editor_open(app_widgets*w){
    lt48_config_memory_resources*r=NULL;if(lt48_config_memory_open(w->installation,w->selected_device_index,&r)!=LT48_OK)return;
    unsigned mask=lt48_config_memory_configuration_mask(r);lt48_config_memory_close(r);
    config_memory_editor*e=g_new0(config_memory_editor,1);e->w=w;e->mask=mask;e->device=w->selected_device_index;e->revision=w->operation_input_revision;
    e->window=GTK_WINDOW(gtk_window_new());gtk_window_set_title(e->window,"Configuration memory options");gtk_window_set_transient_for(e->window,w->window);gtk_window_set_modal(e->window,TRUE);
    GtkWidget*box=gtk_box_new(GTK_ORIENTATION_VERTICAL,8);gtk_window_set_child(e->window,box);
    gtk_box_append(GTK_BOX(box),gtk_label_new(mask==1?"Requested reset polarity. The current setting and array are checked before and after changing it.":"Requested options and hexadecimal user code. Erase is required to restore cleared user-code bits or disable programmed options. Use Secure separately to protect the array."));
    const char*labels[]={"D4/CF pin used as CF", "Secure (use the separate Secure operation)", "Parallel mode enabled"};
    for(unsigned i=0;i<3;i++)if((mask==1&&i==0)||(mask!=1&&(mask&(1u<<(20+i)))&&i!=1)){
        e->flags[i]=gtk_check_button_new_with_label(mask==1?"Reset polarity High":labels[i]);gtk_box_append(GTK_BOX(box),e->flags[i]);
    }
    if(mask!=1){gtk_box_append(GTK_BOX(box),gtk_label_new("32-bit user code (hex)"));e->code=gtk_entry_new();gtk_editable_set_text(GTK_EDITABLE(e->code),"FFFFFFFF");gtk_box_append(GTK_BOX(box),e->code);}
    GtkWidget*apply=gtk_button_new_with_label("Prepare configuration");gtk_box_append(GTK_BOX(box),apply);g_signal_connect(apply,"clicked",G_CALLBACK(config_memory_apply),e);g_object_set_data_full(G_OBJECT(e->window),"configuration-editor",e,g_free);gtk_window_present(e->window);
}

