    if((operation==LT48_OPERATION_SECURE || operation==LT48_OPERATION_CONFIGURATION) && widgets->installation && widgets->has_selected_device && ((!strcmp(lt48_installation_complete_operation_profile(widgets->installation,widgets->selected_device_index),"spd-nine-operation") || !strcmp(lt48_installation_complete_operation_profile(widgets->installation,widgets->selected_device_index),"at17-compact-eight-operation")) || !strcmp(lt48_installation_complete_operation_profile(widgets->installation,widgets->selected_device_index),"page-i2c-nine-operation") || !strcmp(lt48_installation_complete_operation_profile(widgets->installation,widgets->selected_device_index),"at17n-eight-operation"))){spd_editor_open(widgets,operation);return;}
